begin;
do $$
declare admin_id uuid; c1 uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();s1 uuid:=gen_random_uuid();s2 uuid:=gen_random_uuid();s3 uuid:=gen_random_uuid(); plan_id uuid;past_id uuid;future_id uuid;other_id uuid;ex_id uuid; blocked boolean;today date:=timezone('Asia/Tehran',now())::date;receipt text;payload jsonb;
begin
 select id into admin_id from public.profiles where role='admin' limit 1;
 if admin_id is null then raise exception 'Admin fixture bootstrap unavailable';end if;
 insert into auth.users(id,email) select id,id::text||'@test.invalid' from unnest(array[c1,c2,s1,s2,s3]) id;
 if exists(select 1 from public.profiles where id=any(array[s1,s2,s3]) and registration_status<>'incomplete')then raise exception 'New students must be inactive';end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 update public.profiles set role='counselor' where id=any(array[c1,c2]);
 insert into public.counselor_profiles(user_id,approval_status) values(c1,'approved'),(c2,'approved');
 receipt:=s1::text||'/fixture.png';
 insert into storage.objects(bucket_id,name,metadata) values('registration-receipts',receipt,'{"mimetype":"image/png","size":100}'),('registration-receipts',s2::text||'/fixture.png','{"mimetype":"image/png","size":100}');
 payload:=jsonb_build_object('first_name','علی','last_name','احمدی','phone','09121234567','telegram_id','student_1','grade',11,'study_field','humanities','province','تهران','city','تهران','receipt_path',receipt,'receipt_name','receipt.png');
 perform set_config('request.jwt.claim.sub',s1::text,true);
 execute 'set local role authenticated';
 blocked:=false;begin perform public.submit_student_registration(payload-'last_name');exception when others then blocked:=true;end;if not blocked then raise exception 'Incomplete registration accepted';end if;
 perform public.submit_student_registration(payload);
 if has_column_privilege('authenticated','public.profiles','registration_status','update')then raise exception 'Students can self activate';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.admin_assign_student_counselor(s3,c1);
 if exists(select 1 from public.profiles where id=s3 and registration_status<>'active')or not exists(select 1 from public.counselor_students where student_id=s3 and counselor_id=c1)then raise exception 'Assignment must activate the student';end if;
 perform set_config('request.jwt.claim.sub',c1::text,true);
 execute 'set local role authenticated';
 blocked:=false;begin perform public.admin_assign_student_counselor(s2,c1);exception when others then blocked:=true;end;if not blocked then raise exception 'Counselor can assign via admin RPC';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 delete from public.counselor_students where student_id=s3;
 update public.profiles set registration_status='incomplete' where id=s3; -- Reset fixture for separate receipt-activation tests.
 blocked:=false;begin perform public.admin_activate_student(s3,c1,null);exception when others then blocked:=true;end;if not blocked then raise exception 'Missing registration activated';end if;
 blocked:=false;begin perform public.admin_activate_student(s1,c1,'stale');exception when others then blocked:=true;end;if not blocked then raise exception 'Stale receipt activated';end if;
 if exists(select 1 from public.counselor_students where student_id=s1)then raise exception 'Failed approval assigned a counselor';end if;
 perform public.admin_activate_student(s1,c1,receipt);
 if not exists(select 1 from public.profiles where id=s1 and registration_status='active')or not exists(select 1 from public.counselor_students where student_id=s1 and counselor_id=c1)then raise exception 'Activation must assign atomically';end if;
 perform set_config('request.jwt.claim.sub',s2::text,true);
 perform public.submit_student_registration(jsonb_set(payload,'{receipt_path}',to_jsonb(s2::text||'/fixture.png')));
 perform set_config('request.jwt.claim.sub',c1::text,true);
 execute 'set local role authenticated';
 if (select count(*) from public.counselor_student_directory())<>1 then raise exception 'Counselor sees other students';end if;
 if (select count(*) from public.registration_directory())<>1 then raise exception 'Export leaks global directory';end if;
 if exists(select 1 from public.student_registrations where student_id=s2)then raise exception 'Counselor reads unassigned registration';end if;
 if exists(select 1 from storage.objects where bucket_id='registration-receipts' and name=s2::text||'/fixture.png')then raise exception 'Counselor reads unassigned receipt';end if;
 blocked:=false;begin perform public.counselor_select_student(s2);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Counselor can self assign via RPC';end if;
 blocked:=false;begin insert into public.counselor_students(counselor_id,student_id)values(c1,s2);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Counselor can self assign directly';end if;
 execute 'reset role';
 -- Legacy active profiles can be assigned without being forced through new registration.
 update public.profiles set registration_status='active' where id=s3;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);perform public.admin_activate_student(s3,c2,null);
 insert into public.weekly_plans(counselor_id,student_id,week_start,title,status)values(c1,s1,today-2,'Fixture plan','published')returning id into plan_id;
 insert into public.weekly_plan_items(plan_id,day_of_week,duration_minutes,subject,activity_type,target_test_count)values(plan_id,0,60,'فارسی ۲','practice_tests',20)returning id into past_id;
 insert into public.weekly_plan_items(plan_id,day_of_week,duration_minutes,subject,activity_type)values(plan_id,6,60,'فارسی ۲','lesson')returning id into future_id;
 perform set_config('request.jwt.claim.sub',s1::text,true);
 execute 'set local role authenticated';
 perform public.set_weekly_plan_item_progress(past_id,true,9);
 perform public.set_weekly_plan_item_progress(past_id,true,10);
 if not exists(select 1 from public.weekly_plan_item_completions where item_id=past_id and completed_test_count=10)then raise exception 'Past progress not editable';end if;
 perform public.set_weekly_plan_item_progress(past_id,false,null);
 if exists(select 1 from public.weekly_plan_item_completions where item_id=past_id)then raise exception 'Past tick not removable';end if;
 blocked:=false;begin perform public.set_weekly_plan_item_progress(future_id,true,null);exception when others then blocked:=true;end;if not blocked then raise exception 'Future tick allowed';end if;
 blocked:=false;begin perform public.submit_student_registration(payload);exception when others then blocked:=true;end;if not blocked then raise exception 'Active registration mutable';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',s2::text,true);
 execute 'set local role authenticated';
 blocked:=false;begin perform public.set_weekly_plan_item_progress(past_id,true,10);exception when others then blocked:=true;end;if not blocked then raise exception 'Another student can edit progress';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',c1::text,true);
 execute 'set local role authenticated';
 blocked:=false;begin perform public.set_weekly_plan_item_progress(past_id,true,10);exception when others then blocked:=true;end;if not blocked then raise exception 'Counselor can change student progress';end if;
 -- School track supports grade 10 and is not tied to a final-exam year.
 other_id:=public.save_weekly_plan_v4(null,s1,today+7,'School fixture',null,'draft','[{"dayOfWeek":0,"durationMinutes":60,"subject":"فارسی ۱","chapter":"مبحث آزاد","activityType":"notes","targetTestCount":null,"details":"","sourceGrade":10,"preparationTrack":"final_exam","examYear":null}]'::jsonb);
 if not exists(select 1 from public.weekly_plan_items i where i.plan_id=other_id and source_grade=10 and preparation_track='final_exam' and exam_year is null)then raise exception 'Grade-10 school item unavailable';end if;
 blocked:=false;begin perform public.save_weekly_plan_v4(null,s1,today+14,'Invalid fixture',null,'draft','[{"dayOfWeek":0,"durationMinutes":60,"subject":"not a school subject","activityType":"notes","sourceGrade":10,"preparationTrack":"final_exam"}]'::jsonb);exception when others then blocked:=true;end;if not blocked then raise exception 'Unlisted school subject accepted';end if;
 perform public.save_weekly_plan_v4(plan_id,s1,today-2,'Fixture plan',null,'published','[{"dayOfWeek":6,"durationMinutes":60,"subject":"فارسی ۱","chapter":"مبحث آزاد","activityType":"notes","targetTestCount":null,"details":"","sourceGrade":10,"preparationTrack":"final_exam","examYear":null}]'::jsonb);
 if not exists(select 1 from public.weekly_plan_items where id=past_id and subject='فارسی ۲' and target_test_count=20)then raise exception 'Counselor rewrote past activity';end if;
 execute 'reset role';
 -- A shared exam still exposes only the current counselor's students.
 insert into public.exams(counselor_id,title,mode,audience,starts_at,duration_minutes,status)values(c1,'Shared fixture','booklet','all_assigned_students',now()+interval '1 day',15,'draft')returning id into ex_id;
 insert into public.exam_attempts(exam_id,student_id,answers)values(ex_id,s1,'{}'),(ex_id,s3,'{}');
 perform set_config('request.jwt.claim.sub',c1::text,true);
 execute 'set local role authenticated';
 if (select count(*) from public.exam_attempts where exam_id=ex_id)<>1 then raise exception 'Exam participant count leaks other students';end if;
 if (select count(*) from public.exam_attempts_for_counselor(ex_id))<>1 then raise exception 'Exam report RPC leaks other students';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 if (select count(*) from public.exam_attempts_for_counselor(ex_id))<>2 then raise exception 'Admin shared exam reporting changed';end if;
 if (select count(*) from public.registration_directory() where student_id=any(array[s1,s2,s3]))<>3 then raise exception 'Admin cannot see all statuses';end if;
end;$$;
select 'Registration, atomic activation, scoped exports, receipt RLS, assignment restrictions and past activity tests passed' as result;
rollback;
